get_dashboard_report_quick.code:
final response = await client.dashboardReports.getDashboardReportQuick(
  queryParams: {
    'duration': 'last_12_months',
    'kpis': 'total_sales,aov',
    'entity_name': 'product',
  },
);
final report = response.map as Map;
print((report['orders'] as Map)['count']);
for (final kpi in report['kpis'] as List) {
  print('${(kpi as Map)['key']} ${kpi['value']} ${kpi['direction']}');
}

get_dashboard_report_sales.code:
final response = await client.dashboardReports.getDashboardReportSales(
  queryParams: {
    'duration': 'last_12_months',
    'breakdown': 'true',
    'sort': 'sales',
    'order': 'desc',
  },
);
final report = response.map as Map;
for (final row in report['rows'] as List) {
  print('${(row as Map)['label']} ${row['sales']}');
}
print((report['totals'] as Map)['sales']);

